solution:
fn max(a: Int, b: Int) -> Int
  ensures: result >= a;
  ensures: result >= b;
  ensures: result == a || result == b;
{
  if a > b { return a; }
  return b;
}

fn main() -> Int {
  return max(7, 42);
}
